import React, { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

// Register the ScrollTrigger plugin
gsap.registerPlugin(ScrollTrigger);

const ProductAndServices = () => {
  // Refs for the cards to animate
  const card1Ref = useRef(null);
  const card2Ref = useRef(null);
  const card3Ref = useRef(null);

  useEffect(() => {
    // Set up the GSAP animation
    gsap.to(card1Ref.current, {
      scrollTrigger: {
        trigger: card1Ref.current,
        start: "top center",
        end: "bottom center",
        scrub: true, // Smooth scrolling effect
        pin: true, // Pins the card in place during scroll
      },
      y: 0, // Move to original position
      opacity: 1, // Ensure full visibility
      zIndex: 1, // Ensure correct stacking order
    });

    gsap.to(card2Ref.current, {
      scrollTrigger: {
        trigger: card2Ref.current,
        start: "top center",
        end: "bottom center",
        scrub: true,
        pin: true,
      },
      y: -200, // Adjust to overlap the first card
      opacity: 1,
      zIndex: 2, // Ensure it's above the first card
    });

    gsap.to(card3Ref.current, {
      scrollTrigger: {
        trigger: card3Ref.current,
        start: "top center",
        end: "bottom center",
        scrub: true,
        pin: true,
      },
      y: -400, // Adjust to overlap both previous cards
      opacity: 1,
      zIndex: 3, // Ensure it's above the first and second card
    });
  }, []);

  return (
    <section className="py-16 bg-primary-light border-t border-b border-blue-300 relative" id="product">
      <div className="container mx-auto">
        <h2 className="text-3xl font-bold text-center mb-8 text-white">
          PRODUCTS & SERVICES
        </h2>

        {/* Wrapper for cards */}
        <div className="relative h-[1200px] overflow-hidden">

          {/* First Card */}
          <div ref={card1Ref} className="absolute w-full top-0 left-0 z-10 opacity-0 card">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img
                className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg"
                src="./images/Cricket.jpg"
                alt="Cricket Image"
              />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  MATCH GRAPHICS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Our Match Graphics service is designed to bring real-time, data-driven visuals to your live sports broadcasts...
                </p>
              </div>
            </div>
          </div>

          {/* Second Card */}
          <div ref={card2Ref} className="absolute w-full top-40 left-0 z-20 opacity-0 card">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img
                className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg"
                src="./images/Cricket2.jpg"
                alt="Cricket Image"
              />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  LIVE STATS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Our live stats service provides comprehensive, real-time statistics to enhance your live broadcasts...
                </p>
              </div>
            </div>
          </div>

          {/* Third Card */}
          <div ref={card3Ref} className="absolute w-full top-80 left-0 z-30 opacity-0 card">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img
                className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg"
                src="./images/Cricket3.jpg"
                alt="Cricket Image"
              />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  TEAM LINEUPS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Display complete team lineups dynamically in your broadcasts for better engagement with viewers...
                </p>
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
};

export default ProductAndServices;
